function is_multiply_prime(a: number): boolean {
    function is_prime(n: number): boolean {
        for (let j = 2; j < n; j++) {
            if (n % j === 0) {
                return false;
            }
        }
        return true;
    }

    for (let i = 2; i <= 100; i++) {
        if (!is_prime(i)) {
            continue;
        }
        for (let j = 2; j <= 100; j++) {
            if (!is_prime(j)) {
                continue;
            }
            for (let k = 2; k <= 100; k++) {
                if (!is_prime(k)) {
                    continue;
                }
                if (i * j * k === a) {
                    return true;
                }
            }
        }
    }
    return false;
}

function by_length(arr: number[]): string[] {
    const dic: { [key: number]: string } = {
