function get_row(lst: number[][], x: number): [number, number][] {
    const coords: [number, number][] = [];
    for (let i = 0; i < lst.length; i++) {
        for (let j = 0; j < lst[i].length; j++) {
            if (lst[i][j] === x) {
                coords.push([i, j]);
            }
        }
    }
    return coords.sort((a, b) => a[1] - b[1]).sort((a, b) => a[0] - b[0]);
}

function tri(n: number): number[] {
    if (n === 0) {
        return [1];
    }
    const myTri: number[] = [1, 3];
    for (let i = 2; i <= n; i++) {
        if (i % 2 === 0) {
            myTri.push(i / 2 + 1);
        } else {
            myTri.push(myTri[i - 1] + myTri[i - 2] + (i + 3) / 2);
        }
    }
    return myTri;
}

function maximum(arr: number[], k: number): number[] {
    if (k === 0) {
        return [];
    }
    arr.sort((a, b) => a - b);
    const ans = arr.slice(-k);
    return ans;
}

function remove_duplicates(numbers: number[]): number[] {
    const c = new Map<number, number>();
    for (const n of numbers) {
        c.set(n, (c.get(n) || 0) + 1);
    }
    return numbers.filter(n => c.get(n)! <= 1);
}

