function is_nested(string: string): boolean {
    const opening_bracket_index: number[] = [];
    const closing_bracket_index: number[] = [];

    for (let i = 0; i < string.length; i++) {
        if (string[i] === '[') {
            opening_bracket_index.push(i);
        } else {
            closing_bracket_index.push(i);
        }
    }

    closing_bracket_index.reverse();
    let cnt = 0;
    let i = 0;
    const l = closing_bracket_index.length;

    for (const idx of opening_bracket_index) {
        if (i < l && idx < closing_bracket_index[i]) {
            cnt += 1;
            i += 1;
        }
    }

    return cnt >= 2;
}

function order_by_points(nums: number[]): number[] {
    function digitsSum(n: number): number {
        let neg = 1;
        if (n < 0) {
            n *= -1;
            neg = -1;
        }
        const digits = Array.from(n.toString()).map(Number);
        digits[0] *= neg;
        return digits.reduce((acc, digit) => acc + digit, 0);
    }

    return nums.slice().sort((a, b) => digitsSum(a) - digitsSum(b));
}

