function get_closest_vowel(word: string): string {
    if (word.length < 3) {
        return '';
    }
    const vowels = new Set(['a', 'e', 'i', 'o', 'u', 'A', 'E', 'O', 'U', 'I']);
    for (let i = word.length - 2; i > 0; i--) {
        if (vowels.has(word[i])) {
            if (!vowels.has(word[i + 1]) && !vowels.has(word[i - 1])) {
                return word[i];
            }
        }
    }
    return '';
}

function sort_array(array: number[]): number[] {
    if (array.length === 0) {
        return [];
    }
    const reverse = (array[0] + array[array.length - 1]) % 2 === 0;
    return array.slice().sort((a, b) => reverse ? b - a : a - b);
}

