func sort_even(l []int) []int {
    evens := make([]int, 0)
    odds := make([]int, 0)

    for i, v := range l {
        if i%2 == 0 {
            evens = append(evens, v)
        } else {
            odds = append(odds, v)
        }
    }

    sort.Ints(evens)

    ans := make([]int, 0)
    for i := 0; i < len(odds); i++ {
        ans = append(ans, evens[i])
        ans = append(ans, odds[i])
    }

    if len(evens) > len(odds) {
        ans = append(ans, evens[len(evens)-1])
    }

    return ans
}

