func find_closest_elements(numbers []float64) []interface{} {
    var closestPair []interface{}
    var distance float64 = math.MaxFloat64

    for idx, elem := range numbers {
        for idx2, elem2 := range numbers {
            if idx != idx2 {
                newDistance := math.Abs(elem - elem2)
                if newDistance < distance {
                    distance = newDistance
                    closestPair = []interface{}{math.Min(elem, elem2), math.Max(elem, elem2)}
                }
            }
        }
    }

    return closestPair
}

