func is_nested(myString string) bool {
    var openingBracketIndex []int
    var closingBracketIndex []int

    for i, char := range myString {
        if char == '[' {
            openingBracketIndex = append(openingBracketIndex, i)
        } else {
            closingBracketIndex = append(closingBracketIndex, i)
        }
    }

    l := len(closingBracketIndex)
    for i := 0; i < l/2; i++ {
        closingBracketIndex[i], closingBracketIndex[l-1-i] = closingBracketIndex[l-1-i], closingBracketIndex[i]
    }

    cnt := 0
