		neg := 1
		if n < 0 {
			n, neg = -n, -1
		}
		sum := 0
		for _, digitChar := range strconv.Itoa(n) {
			digit := int(digitChar - '0')
			if digit == 0 {
				continue
			}
			sum += digit * neg
		}
		return sum
	}

	sortedNums := make([]int, len(nums))
	copy(sortedNums, nums)
	sort.Slice(sortedNums, func(i, j int) bool {
		return digitsSum(sortedNums[i]) < digitsSum(sortedNums[j])
	})
	return sortedNums
}

