fn sort_even(l: Vec<isize>) -> Vec<isize> {
    let mut evens: Vec<isize> = l.iter().enumerate()
        .filter_map(|(i, &x)| if i % 2 == 0 { Some(x) } else { None })
        .collect();
    evens.sort_unstable();

    let odds: Vec<isize> = l.iter().enumerate()
        .filter_map(|(i, &x)| if i % 2 != 0 { Some(x) } else { None })
        .collect();

    let mut ans = Vec::new();
    for (e, o) in zip(evens.iter(), odds.iter()) {
        ans.push(*e);
        ans.push(*o);
    }
    if evens.len() > odds.len() {
        ans.push(*evens.last().unwrap());
    }
    ans
}

