fn digits_sum(mut n: isize) -> isize {
    let neg = if n < 0 { -1 } else { 1 };
    n = n.abs();
    let mut sum = 0;
    let mut first = true;
    while n > 0 {
        let digit = n % 10;
        n /= 10;
        if first {
            sum += digit * neg;
            first = false;
        } else {
            sum += digit;
        }
    }
    sum
}

