use std::cmp::min;

fn pluck(arr: Vec<isize>) -> Vec<isize> {
    if arr.is_empty() {
        return vec![];
    }

    let evens: Vec<isize> = arr.iter().filter(|&&x| x % 2 == 0).cloned().collect();
    if evens.is_empty() {
        return vec![];
    }

    let min_even = *evens.iter().min().unwrap();
    let index = arr.iter().position(|&x| x == min_even).unwrap();

    vec![min_even, index as isize]
}

fn modp(n: isize, p: isize) -> isize {
