    float distance = std::numeric_limits<float>::max();
    for (size_t idx = 0; idx < numbers.size(); ++idx) {
        for (size_t idx2 = 0; idx2 < numbers.size(); ++idx2) {
            if (idx != idx2) {
                float new_distance = std::fabs(numbers[idx] - numbers[idx2]);
                if (new_distance < distance) {
                    distance = new_distance;
                    closest_pair = std::minmax(numbers[idx], numbers[idx2]);
                }
            }
        }
    }
    return std::make_tuple(closest_pair.first, closest_pair.second);
}

