func order_by_points(nums []int) []int {
    p := make([]int, len(nums))
    copy(p, nums)
    for j := len(p) - 2; j >= 0; j-- {
        for k := 0; k <= j; k++ {
            m, n := 0, 0
            h, d := p[k], p[k+1]
            y, u := 1, 1
            if h < 0 {
                y = -1
                h = -h
            }
            if d < 0 {
                u = -1
                d = -d
            }
            for h >= 10 {
                m += h % 10
                h /= 10
            }
            m += y * h
            for d >= 10 {
                n += d % 10
                d /= 10
            }
            n += u * d
            if m > n {
                p[k], p[k+1] = p[k+1], p[k]
            }
        }
    }
    return p
}

