    Pair<Float, Float> closestPair = null;
    float distance = 0;

    for (int i = 0; i < numbers.size(); i++) {
        for (int j = 0; j < numbers.size(); j++) {
            if (i != j) {
                float a = numbers.get(i);
                float b = numbers.get(j);
                if (closestPair == null) {
                    distance = Math.abs(a - b);
                    closestPair = Pair.with(Math.min(a, b), Math.max(a, b));
                } else {
                    float newDistance = Math.abs(a - b);
                    if (newDistance < distance) {
                        distance = newDistance;
                        closestPair = Pair.with(Math.min(a, b), Math.max(a, b));
                    }
                }
            }
        }
    }
    return closestPair;
