        for (int j = 0; j < numbers.Count; j++) {
            if (i != j) {
                float a = numbers[i];
                float b = numbers[j];
                if (!distance.HasValue) {
                    distance = Math.Abs(a - b);
                    closestPair = Tuple.Create(Math.Min(a, b), Math.Max(a, b));
