    var result = new List<string>();

    foreach (var word in words) {
        int len = word.Length;
        bool isPrime = true;
        if (len <= 1) continue;
        for (int i = 2; i * i <= len; i++) {
            if (len % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            result.Add(word);
        }
    }

    return string.Join(" ", result);
}

