fn find_closest_elements(numbers: Vec<f64>) -> (f64, f64) {
    let mut closest_pair = (0.0, 0.0);
    let mut distance = None;

    for i in 0..numbers.len() {
        for j in 0..numbers.len() {
            if i != j {
                let a = numbers[i];
                let b = numbers[j];
                let new_distance = (a - b).abs();

                match distance {
                    None => {
                        distance = Some(new_distance);
                        closest_pair = if a < b { (a, b) } else { (b, a) };
                    }
                    Some(d) if new_distance < d => {
                        distance = Some(new_distance);
                        closest_pair = if a < b { (a, b) } else { (b, a) };
                    }
                    _ => {}
                }
            }
        }
    }

    closest_pair
}

