fn is_nested(string: String) -> bool {
    let mut opening_bracket_index = Vec::new();
    let mut closing_bracket_index1 = Vec::new();

    for (i, c) in string.chars().enumerate() {
        if c == '[' {
            opening_bracket_index.push(i);
        } else {
            closing_bracket_index1.push(i);
        }
    }

    let mut closing_bracket_index: VecDeque<usize> = closing_bracket_index1.into_iter().rev().collect();
    let mut cnt = 0;
    let mut i = 0;

    for &open_index in &opening_bracket_index {
        if i < closing_bracket_index.len() && open_index < closing_bracket_index[i] {
            cnt += 1;
            i += 1;
        }
    }

    cnt >= 2
}

fn order_by_points(mut nums: Vec<isize>) -> Vec<isize> {
    for j in (0..nums.len() - 1).rev() {
        for k in 0..=j {
            let mut m = 0;
            let mut n = 0;
            let mut h = nums[k];
            let mut d = nums[k + 1];
            let y = if h < 0 { h = -h; -1 } else { 1 };
            let u = if d < 0 { d = -d; -1 } else { 1 };

            while h >= 10 {
                m += h % 10;
                h /= 10;
            }
            m += y * h;

            while d >= 10 {
                n += d % 10;
                d /= 10;
            }
            n += u * d;

            if m > n {
                nums.swap(k, k + 1);
            }
        }
    }
    nums
}

