fn fib4(n: isize) -> isize {
    let mut results = vec![0, 0, 2, 0];
    if n < 4 {
        return results[n as usize];
    }
    for i in 4..=n {
        let next_value = results.iter().sum();
        results.remove(0);
        results.push(next_value);
    }
    results.pop().unwrap()
}

