    if (n == 1) { return {1, 3}; }
    std::vector<long> p = {1, 3};
    for (long i = 2; i <= n; i++) {
        if (i % 2 == 0) {
            p.push_back(1 + i / 2);
        } else {
            p.push_back(p[i - 2] + p[i - 1] + 1 + (i + 1) / 2);
        }
    }
    return p;
}

