        size_t ind = j;
        for (size_t k = j + 1; k < arr.size(); ++k) {
            if (arr[k] < arr[ind]) {
                ind = k;
            }
        }
        if (ind > j) {
            std::swap(arr[j], arr[ind]);
        }
    }
    if (k == 0) { return {}; }
    return std::vector<long>(arr.end() - k, arr.end());
}

std::vector<long> remove_duplicates(std::vector<long> numbers) {
    std::unordered_map<long, int> dict;
    for (const long num : numbers) {
        if (dict.find(num) != dict.end()) {
            dict[num] += 1;
        } else {
            dict[num] = 1;
        }
    }
    std::vector<long> result;
    for (const long x : numbers) {
        if (dict[x] <= 1) {
            result.push_back(x);
        }
    }
    return result;
}

