std::tuple<float, float> find_closest_elements(std::vector<float> numbers) {
    std::pair<float, float> closest_pair;
    float distance = std::numeric_limits<float>::max();
    for (size_t i = 0; i < numbers.size(); ++i) {
        for (size_t j = 0; j < numbers.size(); ++j) {
            if (i != j) {
                float a = numbers[i], b = numbers[j];
                float new_distance = std::abs(a - b);
                if (new_distance < distance) {
                    distance = new_distance;
                    closest_pair = std::minmax(a, b);
                }
            }
        }
    }
    return std::make_tuple(closest_pair.first, closest_pair.second);
}

