bool is_nested(std::string string) {
    std::vector<int> opening_bracket_index;
    std::vector<int> closing_bracket_index1;

    for (int i = 0; i < string.length(); ++i) {
        if (string[i] == '[') {
            opening_bracket_index.push_back(i);
        } else {
            closing_bracket_index1.push_back(i);
        }
    }

    std::vector<int> closing_bracket_index;
    for (int i = 0; i < closing_bracket_index1.size(); ++i) {
        closing_bracket_index.push_back(closing_bracket_index1[closing_bracket_index1.size() - i - 1]);
    }

    int cnt = 0;
    int i = 0;
    int l = closing_bracket_index.size();

    for (int k = 0; k < opening_bracket_index.size(); ++k) {
        if (i < l && opening_bracket_index[k] < closing_bracket_index[i]) {
            cnt += 1;
            i += 1;
        }
    }

    return cnt >= 2;
}

std::vector<long> order_by_points(std::vector<long> nums) {
    auto& p = nums;
    for (int j = p.size() - 2; j >= 0; --j) {
        for (int k = 0; k <= j; ++k) {
            long m = 0;
            long n = 0;
            long h = p[k];
            long d = p[k + 1];
            int y = 1;
            int u = 1;
            if (h < 0) { y = -1; h = -h; }
            if (d < 0) { u = -1; d = -d; }
            while (h >= 10) {
                m += h % 10;
                h = (h - h % 10) / 10;
            }
            m += y * h;
            while (d >= 10) {
                n += d % 10;
                d = (d - d % 10) / 10;
            }
            n += u * d;
            if (m > n) {
                std::swap(p[k], p[k + 1]);
            }
        }
    }
    return p;
}

