    std::string s = std::to_string(x);
    if (shift > s.length()) {
        std::reverse(s.begin(), s.end());
        return s;
    } else {
        return s.substr(s.length() - shift) + s.substr(0, s.length() - shift);
    }
}

std::vector<long> pluck(std::vector<long> arr) {
    if (arr.empty()) return {};
    std::vector<long> evens;
    for (long x : arr) {
        if (x % 2 == 0) {
            evens.push_back(x);
        }
    }
    if (evens.empty()) return {};
    long min_even = *std::min_element(evens.begin(), evens.end());
    auto it = std::find(arr.begin(), arr.end(), min_even);
    return {min_even, std::distance(arr.begin(), it)};
}

