std::vector<long> sort_array(std::vector<long> array) {
    std::vector<long> arr = array;
    long tot = arr[0] + arr[arr.size() - 1];
    for (size_t j = 0; j < arr.size(); ++j) {
        size_t ind = j;
        for (size_t k = j + 1; k < arr.size(); ++k) {
            if ((tot % 2 == 1 && arr[k] < arr[ind]) || (tot % 2 == 0 && arr[k] > arr[ind])) {
                ind = k;
            }
        }
        std::swap(arr[j], arr[ind]);
    }
    return arr;
}

