long fib4(long n) {
    std::vector<long> results = {0, 0, 2, 0};
    if (n < 4)
        return results[n];
    for (long i = 4; i < n + 1; ++i) {
        long next_value = results[3] + results[2] + results[1] + results[0];
        results.push_back(next_value);
        results.erase(results.begin());
    }
    return results.back();
}

