std::string words_in_sentence(std::string sentence) {
    std::istringstream iss(sentence);
    std::vector<std::string> t;
    std::string word;
    while (iss >> word) {
        t.push_back(word);
    }
    std::string p = "";
    for (const auto& w : t) {
        int len = w.length();
        bool u = true;
        if (len == 1 || len == 0) { continue; }
        for (int i = 2; i * i <= len; ++i) {
            if (len % i == 0) { u = false; }
        }
        if (!u) { continue; }
        if (p.empty()) { p += w; }
        else { p += " " + w; }
    }
    return p;
}

std::string match_parens(std::vector<std::string> lst) {
    std::string w1 = lst[0] + lst[1];
    int y = 0;
    int u = 1;
    for (char c : w1) {
        if (c == '(') { y++; }
        else { y--; }
        if (y < 0) {
            u = 0;
            break;
        }
    }
    if (u == 1 && y == 0) { return "Yes"; }

    w1 = lst[1] + lst[0];
    y = 0;
    u = 1;
    for (char c : w1) {
        if (c == '(') { y++; }
        else { y--; }
        if (y < 0) {
            u = 0;
            break;
        }
    }
    if (u == 1 && y == 0) { return "Yes"; }

    return "No";
}

