func split_words(txt: String) -> Result<[String], Int> {
    let whitespaceSplit = txt.split(separator: " ").map { String($0) }
    if whitespaceSplit.count > 1 {
        return .success(whitespaceSplit)
    } else {
        let commaSplit = txt.split(separator: ",").map { String($0) }
        if commaSplit.count > 1 {
            return .success(commaSplit)
        } else {
            let count = txt.filter { $0.isLowercase && Int($0.asciiValue ?? 0) % 2 == 0 }.count
            return .failure(count)
        }
    }
}

