func tri(n: Int) -> [Int] {
    if n == 0 { return [1] }
    if n == 1 { return [1, 3] }

    var p = [1, 3]
    for i in 2...n {
        if i % 2 == 0 {
            p.append(1 + i / 2)
        } else {
            p.append(p[i - 2] + p[i - 1] + 1 + (i + 1) / 2)
        }
    }
    return p
}

