            if p[k] < p[ind] {
                ind = k
            }
        }
        if ind > j {
            let tmp = p[j]
            p[j] = p[ind]
            p[ind] = tmp
        }
    }
    if k == 0 { return [] }
    return Array(p.suffix(k))
}

