        for k in 0...j {
            var m = 0
            var n = 0
            var h = p[k]
            var d = p[k + 1]
            let y = h < 0 ? -1 : 1
            let u = d < 0 ? -1 : 1

            h = abs(h)
            while h >= 10 {
                m += h % 10
                h /= 10
            }
            m += y * h

            d = abs(d)
            while d >= 10 {
                n += d % 10
                d /= 10
            }
            n += u * d

            if m > n {
                let tmp = p[k]
                p[k] = p[k + 1]
                p[k + 1] = tmp
            }
        }
    }

    return p
}

