private static int digitsSum(Long n) {
    int neg = 1;
    if (n < 0) {
        n = -n;
        neg = -1;
    }
    int sum = 0;
    String numStr = Long.toString(n);
    for (int i = 0; i < numStr.length(); i++) {
        if (i == 0) {
            sum += (numStr.charAt(i) - '0') * neg;
        } else {
            sum += (numStr.charAt(i) - '0');
        }
    }
    return sum;
}

