    Tuple<float, float> closestPair = null;

    for (int idx = 0; idx < numbers.Count; idx++) {
        for (int idx2 = 0; idx2 < numbers.Count; idx2++) {
            if (idx != idx2) {
                float newDistance = Math.Abs(numbers[idx] - numbers[idx2]);
                if (newDistance < distance) {
                    distance = newDistance;
                    var pair = Tuple.Create(Math.Min(numbers[idx], numbers[idx2]), Math.Max(numbers[idx], numbers[idx2]));
                    closestPair = pair;
