use std::iter::Iterator;

fn correct_bracketing(mut brackets: String) -> bool {
    brackets.push(' ');
    let mut open = 0;
    let mut chars = brackets.chars().peekable();

    while let Some(c) = chars.next() {
        if c == '(' {
            open += 1;
        } else if c == ')' {
            open -= 1;
            if open < 0 {
                return false;
            }
        } else if c == ' ' && chars.peek() == Some(&')') {
            continue;
        }
    }

    open == 0
}

