fn find_closest_elements(numbers: Vec<f64>) -> (f64, f64) {
    let mut distance = f64::MAX;
    let mut closest_pair = (0.0, 0.0);

    for (idx, &elem) in numbers.iter().enumerate() {
        for (&elem2, idx2) in numbers.iter().enumerate() {
            if idx != idx2 {
                let new_distance = (elem - elem2).abs();
                if new_distance < distance {
                    distance = new_distance;
                    let mut pair = [elem, elem2];
                    pair.sort_by(|a, b| a.partial_cmp(b).unwrap());
                    closest_pair = (pair[0], pair[1]);
