        let chars: Vec<char> = str_n.chars().collect();
        let neg = if chars[0] == '-' { -1 } else { 1 };

        for (i, c) in chars.iter().enumerate() {
            if i == 0 && *c == '-' {
                continue;
            }
            sum += (*c.to_digit(10).unwrap() as isize) * if i == 1 && neg == -1 { -1 } else { 1 };
