use std::iter::FromIterator;

fn circular_shift(x: isize, shift: isize) -> String {
    let s = x.to_string();
    let len = s.len() as isize;
    if shift > len {
        let chars: Vec<char> = s.chars().collect();
        let reversed: String = chars.iter().rev().collect();
        reversed
    } else {
        let shift = shift % len;
        let (left, right) = s.split_at((len - shift) as usize);
        format!("{}{}", right, left)
    }
}

use std::cmp;

fn pluck(arr: Vec<isize>) -> Vec<isize> {
    let mut result = Vec::new();
    if arr.is_empty() {
        return result;
    }

    let mut evens = Vec::new();
    let mut min = isize::MAX;
    let mut min_index = 0;

    for (i, &x) in arr.iter().enumerate() {
        if x % 2 == 0 {
            evens.push(x);
            if x < min {
                min = x;
                min_index = i as isize;
            }
        }
    }

    if !evens.is_empty() {
        result.push(min);
        result.push(min_index);
    }

    result
}

fn modp(n: isize, p: isize) -> isize {
    let mut ret = 1;
    for _ in 0..n {
        ret = (2 * ret % p + p) % p; // Ensure the result is non-negative
    }
    ret
}

