    } else if (txt.find(',') != std::string::npos) {
        std::vector<std::string> words;
        size_t start = 0, end;
        while ((end = txt.find(',', start)) != std::string::npos) {
            words.push_back(txt.substr(start, end - start));
            start = end + 1;
        }
        words.push_back(txt.substr(start));
        return Union_std_vector_std_string__long(words);
    } else {
        long cnt = 0;
        for (char c : txt) {
            if ('a' <= c && c <= 'z' && ((c - 'a') & 1)) {
                cnt++;
            }
        }
        return Union_std_vector_std_string__long(cnt);
    }
}

