}

std::tuple<long, long> even_odd_palindrome(long n) {
    long even_palindrome_count = 0;
    long odd_palindrome_count = 0;

    for (long i = 1; i <= n; ++i) {
        if (i % 2 == 1 && is_palindrome(i)) {
            odd_palindrome_count++;
        } else if (i % 2 == 0 && is_palindrome(i)) {
            even_palindrome_count++;
        }
    }
    return std::make_tuple(even_palindrome_count, odd_palindrome_count);
}

bool correct_bracketing(std::string brackets) {
    std::replace(brackets.begin(), brackets.end(), '(', ' ( ');
    std::replace(brackets.begin(), brackets.end(), ')', ") ");
    int open = 0;
    for (char b : brackets) {
        if (b == '(') {
            open++;
        } else if (b == ')') {
            open--;
        }
        if (open < 0) {
            return false;
        }
    }
    return open == 0;
}

long largest_prime_factor(long n) {
    auto is_prime = [](long n) -> bool {
        for (long i = 2; i <= std::sqrt(n); ++i) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    };

    long largest = 1;
    for (long j = 2; j < n + 1; ++j) {
        if (n % j == 0 && is_prime(j)) {
            if (j > largest) {
                largest = j;
            }
        }
    }
    return largest;
}

