bool is_multiply_prime(long a) {
    for (int i = 2; i < 101; ++i) {
        if (!is_prime(i)) {
            continue;
        }
        for (int j = 2; j < 101; ++j) {
            if (!is_prime(j)) {
                continue;
            }
            for (int k = 2; k < 101; ++k) {
                if (!is_prime(k)) {
                    continue;
                }
                if (static_cast<long>(i) * j * k == a) {
                    return true;
                }
            }
        }
    }
    return false;
}

