std::vector<std::tuple<long, long>> get_row(std::vector<std::vector<long>> lst, long x) {
    std::vector<std::tuple<long, long>> coords;
    for (long i = 0; i < lst.size(); ++i) {
        for (long j = 0; j < lst[i].size(); ++j) {
            if (lst[i][j] == x) {
                coords.emplace_back(i, j);
            }
        }
    }
    std::sort(coords.begin(), coords.end(), [](const std::tuple<long, long>& a, const std::tuple<long, long>& b) {
        if (std::get<0>(a) == std::get<0>(b)) {
            return std::get<1>(a) > std::get<1>(b);
        }
        return std::get<0>(a) < std::get<0>(b);
    });
    return coords;
}

std::vector<long> tri(long n) {
    if (n == 0) {
        return {1};
    }
    std::vector<long> my_tri = {1, 3};
    for (long i = 2; i < n + 1; ++i) {
        if (i % 2 == 0) {
            my_tri.push_back(i / 2 + 1);
        } else {
            my_tri.push_back(my_tri[i - 1] + my_tri[i - 2] + (i + 3) / 2);
        }
    }
    return my_tri;
}

