std::tuple<float, float> find_closest_elements(std::vector<float> numbers) {
    float distance = std::numeric_limits<float>::max();
    std::pair<float, float> closestPair;
    for (size_t idx = 0; idx < numbers.size(); ++idx) {
        for (size_t idx2 = 0; idx2 < numbers.size(); ++idx2) {
            if (idx != idx2) {
                float newDistance = std::abs(numbers[idx] - numbers[idx2]);
                if (newDistance < distance) {
                    distance = newDistance;
                    std::vector<float> pair = {numbers[idx], numbers[idx2]};
                    std::sort(pair.begin(), pair.end());
                    closestPair = {pair[0], pair[1]};
                }
            }
        }
    }
    return closestPair;
}

