bool is_nested(std::string string) {
    std::vector<int> opening_bracket_index;
    std::vector<int> closing_bracket_index;

    for (size_t i = 0; i < string.length(); ++i) {
        if (string[i] == '[') {
            opening_bracket_index.push_back(i);
        } else {
            closing_bracket_index.push_back(i);
        }
    }

    std::reverse(closing_bracket_index.begin(), closing_bracket_index.end());

    int cnt = 0;
    size_t i = 0;
    size_t l = closing_bracket_index.size();

    for (int idx : opening_bracket_index) {
        if (i < l && idx < closing_bracket_index[i]) {
            cnt++;
            i++;
        }
    }

    return cnt >= 2;
}

std::vector<long> order_by_points(std::vector<long> nums) {
    auto digits_sum = [](long n) -> long {
        int neg = 1;
        if (n < 0) {
            n = -n;
            neg = -1;
        }
        long sum = 0;
        std::string num_str = std::to_string(n);
        for (size_t i = 0; i < num_str.length(); ++i) {
            if (i == 0) {
                sum += (num_str[i] - '0') * neg;
            } else {
                sum += num_str[i] - '0';
            }
        }
        return sum;
    };

    std::stable_sort(nums.begin(), nums.end(), [&digits_sum](long a, long b) {
        return digits_sum(a) < digits_sum(b);
    });

    return nums;
}

