import Foundation

func split_words(txt: String) -> Result<[String], Int> {
    if txt.contains(" ") {
        return .success(txt.split(separator: " ").map { String($0) })
    } else if txt.contains(",") {
        return .success(txt.split(separator: ",").map { String($0) })
    } else {
        let count = txt.filter { $0.isLowercaseVowel() }.count
        return .failure(count)
    }
}

private extension Character {
    func isLowercaseVowel() -> Bool {
        guard let scalarValue = unicodeScalars.first?.value else { return false }
        return (scalarValue >= 97 && scalarValue <= 122) && ((scalarValue - 97) & 1 == 1)
    }
