function pluck(arr: number[]): number[] {
    const result: number[] = [];
    if (arr.length === 0) {
        return result;
    }
    let min = Number.MAX_SAFE_INTEGER;
    let minIndex = -1;
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] % 2 === 0) {
            if (arr[i] < min) {
                min = arr[i];
                minIndex = i;
            }
        }
    }
    if (minIndex !== -1) {
        result.push(min);
        result.push(minIndex);
    }
    return result;
}

