    for (int i = 0; i < numbers.Count; i++) {
        for (int j = i + 1; j < numbers.Count; j++) {
            if (Math.Abs(numbers[i] - numbers[j]) < distance) {
                closestPair.Clear();
                closestPair.Add(numbers[i]);
                closestPair.Add(numbers[j]);
