use std::iter::FromIterator;

fn even_odd_palindrome(n: isize) -> (isize, isize) {
    let mut even_palindrome_count = 0;
    let mut odd_palindrome_count = 0;

    for i in 1..=n {
        let str_i = i.to_string();
        let reversed_str_i: String = str_i.chars().rev().collect();
        if str_i == reversed_str_i {
            if i % 2 == 1 {
                odd_palindrome_count += 1;
            } else {
                even_palindrome_count += 1;
            }
        }
    }

    (even_palindrome_count, odd_palindrome_count)
}

use std::collections::VecDeque;

fn correct_bracketing(brackets: String) -> bool {
    let mut depth = 0;
    for b in brackets.chars() {
        if b == '(' {
            depth += 1;
        } else {
            depth -= 1;
        }
        if depth < 0 {
            return false;
        }
    }
    depth == 0
}

fn largest_prime_factor(mut n: isize) -> isize {
    let mut largest = 1;
    let mut j = 2;
    while j <= n {
        if n % j == 0 {
            let mut is_prime = true;
            for i in 2..j {
                if j % i == 0 {
                    is_prime = false;
                    break;
                }
            }
            if is_prime {
                largest = largest.max(j);
            }
            n /= j;
        } else {
            j += 1;
        }
    }
    largest
}

