fn digit_sum(mut num: isize) -> isize {
    let mut sum = 0;
    let negative = num < 0;
    num = num.abs();

    while num > 0 {
        sum += num % 10;
        num /= 10;
    }

    if negative {
        sum = -sum;
    }
    sum
}

