    let mut result = Vec::new();
    if arr.is_empty() {
        return result;
    }
    let mut min = isize::MAX;
    let mut min_index = -1;

    for (i, &value) in arr.iter().enumerate() {
        if value % 2 == 0 {
            if value < min {
                min = value;
                min_index = i as isize;
            }
        }
    }

    if min_index != -1 {
        result.push(min);
        result.push(min_index);
    }

    result
}

