func find_closest_elements(numbers: [Double]) -> (Double, Double) {
    guard numbers.count > 1 else {
        fatalError("The list must contain at least two elements.")
    }

    var closestPair = (numbers[0], numbers[1])
    var distance = abs(numbers[1] - numbers[0])

    for i in 0..<numbers.count {
        for j in i + 1..<numbers.count {
            let currentDistance = abs(numbers[i] - numbers[j])
            if currentDistance < distance {
                closestPair = (numbers[i], numbers[j])
                distance = currentDistance
            }
        }
    }

    return min(closestPair.0, closestPair.1)...max(closestPair.0, closestPair.1).lowerBound
}

