private func digitSum(_ num: Int) -> Int {
    var sum = 0
    let strNum = String(abs(num))
    for (index, char) in strNum.enumerated() {
        if index != 0 || num >= 0 {
            sum += Int(String(char))!
            if index == 1 && num < 0 {
                sum *= -1
            }
        }
    }
    return num < 0 ? -sum : sum
}

