fn even_odd_palindrome(n: isize) -> (isize, isize) {
    let mut num1 = 0;
    let mut num2 = 0;
    for i in 1..=n {
        let w = i.to_string();
        let p: String = w.chars().rev().collect();
        if w == p && i % 2 == 1 {
            num1 += 1;
        }
        if w == p && i % 2 == 0 {
            num2 += 1;
        }
    }
    (num2, num1)
}

fn correct_bracketing(brackets: String) -> bool {
    let mut level = 0;
    for c in brackets.chars() {
        if c == '(' {
            level += 1;
        } else if c == ')' {
            level -= 1;
        }
        if level < 0 {
            return false;
        }
    }
    level == 0
}

fn largest_prime_factor(mut n: isize) -> isize {
    let mut i = 2;
    while i * i <= n {
        while n % i == 0 && n > i {
            n /= i;
        }
        i += 1;
    }
    n
}

