fn tri(n: isize) -> Vec<isize> {
    let mut out = vec![1, 3];
    if n == 0 {
        return vec![1];
    }
    for i in 2..=n {
        if i % 2 == 0 {
            out.push(1 + i / 2);
        } else {
            out.push(out[(i - 1) as usize] + out[(i - 2) as usize] + 1 + (i + 1) / 2);
        }
    }
    out
