        if let char = word.index(word.startIndex, offsetBy: i, limitedBy: word.endIndex), vowels.contains(word[char]) {
            if let nextChar = word.index(char, offsetBy: 1, limitedBy: word.endIndex), !vowels.contains(word[nextChar]) {
                if let prevChar = word.index(char, offsetBy: -1, limitedBy: word.startIndex), !vowels.contains(word[prevChar]) {
                    return String(word[char])
                }
            }
        }
    }
    return ""
}

import Foundation

func sort_array(array: [Int]) -> [Int] {
    if array.isEmpty {
        return []
    }
    let sum = array.first! + array.last!
    var sortedArray = array.sorted()

    if sum % 2 == 1 {
        return sortedArray
    } else {
        return sortedArray.reversed()
    }
}

