func all_prefixes(string: String) -> [String] {
    var out: [String] = []
    var current = ""
    for char in string {
        current += String(char)
        out.append(current)
    }
    return out
}

import Foundation

func can_arrange(arr: [Int]) -> Int {
    var max = -1
    for i in 0..<arr.count {
        if arr[i] <= i {
            max = i
        }
    }
    return max
}

func fib4(n: Int) -> Int {
    if n < 0 {
        return 0
    }

    var f = [Int](repeating: 0, count: max(100, n + 1))
    f[2] = 2

    for i in 4...n {
        f[i] = f[i - 1] + f[i - 2] + f[i - 3] + f[i - 4]
    }

    return f[n]
}

import Foundation

func max_element(l: [Int]) -> Int {
    guard !l.isEmpty else { fatalError("List cannot be empty") }
    var max = l[0]
    for element in l {
        if max < element {
            max = element
        }
    }
    return max
}

import Foundation

func is_bored(S: String) -> Int {
    var isstart = true
    var isi = false
    var sum = 0

    for char in S {
        if char == " " && isi {
            isi = false
            sum += 1
        }
        if char == "I" && isstart {
            isi = true
        } else {
            isi = false
        }
        if char != " " {
            isstart = false
        }
        if char == "." || char == "?" || char == "!" {
            isstart = true
        }
    }

    return sum
}

import Foundation

func words_in_sentence(sentence: String) -> String {
    var out = ""
    var current = ""
    let sentenceWithSpace = sentence + " "

    for char in sentenceWithSpace {
        if char != " " {
            current.append(char)
        } else {
            var isp = true
            let l = current.count
            if l < 2 {
                isp = false
            }
            for j in 2...Int(sqrt(Double(l))) {
                if l % j == 0 {
                    isp = false
                    break
                }
            }
            if isp {
                out.append(current + " ")
            }
            current = ""
        }
    }

    if !out.isEmpty {
        out.removeLast()
    }

    return out
}

func match_parens(lst: [String]) -> String {
    let l1 = lst[0] + lst[1]
    var count = 0
    var can = true
    for char in l1 {
        if char == "(" {
            count += 1
        } else if char == ")" {
            count -= 1
        }
        if count < 0 {
            can = false
        }
    }
    if count != 0 {
        return "No"
    }
    if can {
        return "Yes"
    }

    let l2 = lst[1] + lst[0]
    can = true
    for char in l2 {
        if char == "(" {
            count += 1
        } else if char == ")" {
            count -= 1
        }
        if count < 0 {
            can = false
        }
    }
    if can {
        return "Yes"
    }

    return "No"
}
